-- Holo: watch parties for Worms Ultimate Mayhem. Client-only. This file is generated by tools/build_lua.py from
-- src/*.lua (name order); edit the fragments, not this file. Every fragment is one do ... end block that fills one
-- of the namespace tables below, so the chunk keeps far fewer than 200 top-level locals.
local U, CFG, NET, PARTY, QUEUE, SPOT, MUSIC, LAYOUT, SKIN, W, PUI, SETUP, MUI, MAIN = {}, {}, {}, {}, {}, {}, {}, {},
  {}, {}, {}, {}, {}, {}
local VERSION = "1.1.0"

if not (wum and wum.media and wum.peer and wum.input and wum.draw and wum.draw.hudNine) then
  wum.log.warn("Holo needs Melange 0.12.0 or later (wum.media, wum.peer, wum.input and wum.draw.hudNine); not started")
  return
end

-- Tests read the namespaces through this hook; the real game never defines it.
if wum._holoTest then
  wum._holoTest.ns = {U = U, CFG = CFG, NET = NET, PARTY = PARTY, QUEUE = QUEUE, LAYOUT = LAYOUT, SKIN = SKIN,
    W = W, PUI = PUI, SETUP = SETUP, MAIN = MAIN, SPOT = SPOT, MUSIC = MUSIC, MUI = MUI}
end

do
  -- Log with a level: U.log("info", ...). Unknown levels fall back to info.
  function U.log(level, ...)
    local f = wum.log[level] or wum.log.info
    f("[holo]", ...)
  end

  -- In-file bus. U.emit runs the listeners of a name synchronously, in subscription order; a listener that raises
  -- is logged and skipped, it never stops the others.
  local listeners = {}

  function U.on(name, fn)
    local l = listeners[name]
    if not l then
      l = {}
      listeners[name] = l
    end
    l[#l + 1] = fn
    return fn
  end

  function U.off(name, fn)
    local l = listeners[name]
    if not l then return false end
    for i = 1, #l do
      if l[i] == fn then
        table.remove(l, i)
        return true
      end
    end
    return false
  end

  function U.emit(name, ...)
    local l = listeners[name]
    if not l then return end
    local copy = {table.unpack(l)}
    for i = 1, #copy do
      local ok, err = pcall(copy[i], ...)
      if not ok then U.log("error", "listener", name, err) end
    end
  end

  -- U.guard(name, fn) -> a wrapper that runs fn under pcall. Three errors in a row stop that piece (it then does
  -- nothing and returns nil) and the third is logged once; a success resets the count. Used for every per-frame or
  -- event piece, the Kanly pattern.
  local STRIKES = 3
  function U.guard(name, fn)
    local strikes, dead = 0, false
    return function(...)
      if dead then return end
      local r = table.pack(pcall(fn, ...))
      if r[1] then
        strikes = 0
        return table.unpack(r, 2, r.n)
      end
      strikes = strikes + 1
      U.log("error", name, r[2])
      if strikes >= STRIKES then
        dead = true
        U.log("error", name, "stopped after " .. STRIKES .. " errors")
      end
    end
  end
end
